const assets={"/":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Lunabotics | Project ERP</title><link rel=\"stylesheet\" href=\"style.css\"></head><body><aside><div class=\"brand\">◒ <span>LUNABOTICS<small>PROJECT OPERATIONS / 2027</small></span></div><nav id=\"nav\"></nav><div class=\"sidefoot\">UNIVERSITY AT BUFFALO<br><span>Build something extraordinary.</span></div></aside><main><header><span>2027 ROBOT <b>/</b> OPERATIONS</span><div><button id=\"export\">Export backup</button> <button id=\"import\">Import backup</button></div></header><div class=\"notice\">Connecting to the shared club workspace…</div><section id=\"app\"></section></main><dialog id=\"modal\"></dialog><input type=\"file\" id=\"file\" accept=\"application/json\" hidden><script src=\"logic.js\"></script><script src=\"cloud.js\"></script><script src=\"app.js\"></script></body></html>\r\n","type":"text/html; charset=utf-8"},"/app.js":{"body":"const names=['Drivetrain','Chassis','Shoulder','Legs','Drum','Electronics','Misc','Documentation'];\r\nconst $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])), money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v), uid=()=>crypto.randomUUID();\r\nconst seed={version:1,units:names.map(name=>({name,budget:name==='Electronics'?600:name==='Misc'?300:null,purchase:'',fabricate:'',assemble:''})),parts:[],requirements:[],orders:[]};\r\n[['Wagon',39.99,'https://a.co/d/09brH1Ju'],['Tool Kit',89.99,'https://a.co/d/08lR1nMH'],['Scissors',9.99,'https://a.co/d/0cOEqehO'],['Duct Tape',17.99,'https://a.co/d/04AoNxtV'],['Zip ties',6.99,'https://a.co/d/07nQQhPu']].forEach(([name,price,url],i)=>{const id='misc-'+i;seed.parts.push({id,name,number:'',price,supplier:'Amazon',url,drawing:'',revision:'',type:'Purchased'});seed.requirements.push({id:'r-'+id,part:id,unit:'Misc',qty:1,stage:'Received',received:1,ready:0,location:'',assembly:'',due:'',notes:'Receipt tax/shipping not yet reconciled.'});seed.orders.push({id:'o-'+id,requirement:'r-'+id,qty:1,price,extra:0,date:'',note:'Confirmed received by club; date unknown.'})});\r\nconst mech=[['Hex Bearing',4,4,'FR8ZZ-HexHD','Drum','AndyMark','Received'],['Hex Shaft Collar',6.60,10,'','Drum','AndyMark','Design'],['Pillow Block Bearing',29.20,4,'3813T11','Shoulder','McMaster-Carr','Received'],['Hinge',8.67,2,'1609A24','Shoulder','McMaster-Carr','Received'],['Steel Shaft',26.06,1,'6103N7','Shoulder','McMaster-Carr','Received'],['Gusset Plates',5.29,16,'6791N11','Chassis','McMaster-Carr','Received'],['Bronze Sleeve Bearing',6.31,4,'6391K226','Shoulder','McMaster-Carr','Received'],['Aluminum Round Tube',8.13,1,'9056K36','Shoulder','McMaster-Carr','Received'],['Shaft Collar',2.55,10,'9414T11','Shoulder','McMaster-Carr','Received'],['Hex Shaft',7.12,2,'6512K181','Drum','McMaster-Carr','Received'],['Frame Tubing',118.05,1,'18015','Chassis','OnlineMetals','Received'],['Arm Tubing',183.53,1,'19958','Chassis','OnlineMetals','Received'],['Aluminum Flat Bar',38.09,1,'7541','Chassis','OnlineMetals','Received']];\r\nmech.forEach(([name,price,qty,number,unit,supplier,stage],i)=>{let id='mech-'+i;seed.parts.push({id,name,number,price,supplier,url:supplier==='McMaster-Carr'?'https://www.mcmaster.com/'+number+'/':'',drawing:'',revision:'',type:'Purchased'});seed.requirements.push({id:'r-'+id,part:id,unit,qty,stage,received:stage==='Received'?qty:0,ready:0,location:'',assembly:unit==='Chassis'?'Chassis weldment':'',due:'',notes:'Imported from PDF. Unit assignment is provisional; verify against design.'});if(stage==='Received')seed.orders.push({id:'o-'+id,requirement:'r-'+id,qty,price,extra:0,date:'',note:'PDF marked Received. Verify receipt totals.'})});\r\nlet state=structuredClone(seed);let view='Overview',filter='',search='';const save=()=>cloudSave();const part=r=>state.parts.find(p=>p.id===r.part), reqs=u=>state.requirements.filter(r=>r.unit===u), physical=()=>state.requirements.filter(r=>r.unit!=='Documentation'), sum=(a,fn)=>a.reduce((n,x)=>n+fn(x),0), act=r=>ERP.actual(state,r.id), exp=r=>ERP.expected(state,r), opts=(a,v)=>a.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('');\r\nfunction title(k,h,p,action=''){return `<div class=\"title\"><div><div class=\"eyebrow\">${k}</div><h1>${h}</h1><div class=\"muted\">${p}</div></div>${action}</div>`}\r\nfunction metric(l,v,n){return `<div class=\"metric\"><label>${l}</label><strong>${v}</strong><small>${n}</small></div>`}\r\nfunction badge(s){return `<span class=\"pill ${s==='Design'?'':s==='Released'?'warn':'green'}\">${esc(s)}</span>`}\r\nfunction render(){const nav=['Overview','Units & deadlines','Master parts','Purchasing','Inventory & fabrication','Documentation','Budget'];$('#nav').innerHTML=nav.map((n,i)=>`<button class=\"${view===n?'active':''}\" data-view=\"${n}\">${['◈','▦','≡','↗','▣','▤','$'][i]} &nbsp; ${n}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{view=b.dataset.view;filter='';search='';render()});$('#app').innerHTML=pages[view]();bind()}\r\nfunction unitCard(u){const rs=reqs(u.name), ready=rs.filter(r=>['Ready for assembly','Assembled'].includes(r.stage)).length;return `<article class=\"unit\"><div class=\"unithead\"><h3>${u.name}</h3><span class=\"pill\">${rs.length} ${u.name==='Documentation'?'documents':'components'}</span></div><div class=\"sub\">${u.name==='Documentation'?'Individual deadlines per document':money(sum(rs,exp))+' expected · '+money(sum(rs,act))+' purchased'}</div><div class=\"progress\"><i style=\"width:${rs.length?ready/rs.length*100:0}%\"></i></div>${u.name==='Documentation'?'<p>Manage deadlines in Documentation.</p>':`<div class=\"dates\">${['purchase','fabricate','assemble'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)} by<input type=\"date\" aria-label=\"${u.name} ${k} by\" data-date=\"${k}\" data-unit=\"${u.name}\" value=\"${esc(u[k])}\"></label>`).join('')}</div>`}</article>`}\r\nconst pages={\r\n'Overview':()=>title('MISSION CONTROL','Every part. One project.','From the first drawing to the final assembly.', '<button class=\"primary\" data-add>Add component +</button>')+`<div class=\"metrics\">${metric('Team budget',money(3000),'2027 competition season')}${metric('Expected cost',money(sum(physical(),exp)),'All listed physical components · before unrecorded tax')}${metric('Confirmed purchases',money(sum(physical(),act)),'Recorded purchases, including received stock')}${metric('Ready for assembly',physical().filter(r=>['Ready for assembly','Assembled'].includes(r.stage)).length,'of '+physical().length+' component requirements')}</div><div class=\"banner\">Import review: mechanical unit assignments are provisional. Tax/shipping and receipt totals need reconciliation. The electrical bolt row is excluded pending confirmation because its PDF summary conflicts with the line item. Five Misc items are confirmed received, quantity one each.</div><div class=\"split\"><div><h2>Units at a glance</h2><div class=\"grid\">${state.units.map(unitCard).join('')}</div></div><div class=\"panel\"><div class=\"eyebrow\">WORKFLOW</div><h2>Design to assembly</h2>${ERP.stages.map(s=>`<div class=\"row\"><span>${s}</span><b>${physical().filter(r=>r.stage===s).length}</b></div>`).join('')}<h2>Needs attention</h2><p>${physical().filter(r=>r.received>0&&!r.location).length} received components need a room location.</p><p>${ERP.groups(state).filter(g=>g.held.length).length} purchasing lines have unreleased demand elsewhere.</p><p>${state.units.filter(u=>u.name!=='Documentation'&&u.budget===null).length} unit budgets are unallocated.</p></div></div>`,\r\n'Units & deadlines':()=>title('PROJECT STRUCTURE','Units & deadlines','Physical work follows unit deadlines. Documentation has individual due dates.')+`<div class=\"grid\">${state.units.map(unitCard).join('')}</div><footer>Chassis requirements can share a parent assembly, such as “Chassis weldment”, for welding readiness tracking.</footer>`,\r\n'Master parts':()=>partsPage(false),\r\n'Inventory & fabrication':()=>partsPage(true),\r\n'Documentation':()=>title('DELIVERABLES','Documentation','Track each document, revision, owner notes, and deadline.','<button class=\"primary\" data-doc>Add document +</button>')+table(['Document','Revision','Deadline','Status',''],reqs('Documentation').map(r=>`<tr><td><strong>${esc(part(r).name)}</strong>${safeLink(part(r).drawing,'Open document')}</td><td>${esc(part(r).revision)||'—'}</td><td>${esc(r.due)||'Not scheduled'}</td><td>${badge(r.stage)}</td><td><button data-edit=\"${r.id}\">Edit</button></td></tr>`)),\r\n'Purchasing':()=>title('PROCUREMENT','Purchasing','Identical components share one line. Only released quantities enter the order.')+table(['Component','Released demand','Quantity','Other demand','Purchase by',''],ERP.groups(state).map(g=>{let dates=g.released.map(r=>state.units.find(u=>u.name===r.unit).purchase).filter(Boolean).sort();return `<tr><td><strong>${esc(g.part.name)}</strong><small>${esc(g.part.number)} · ${esc(g.part.supplier)}</small>${safeLink(g.part.url,'Supplier')}</td><td>${g.released.map(r=>esc(r.unit)+' × '+(r.qty-ERP.purchased(state,r.id))).join('<br>')}</td><td>${g.qty}</td><td>${g.held.length?'<span class=\"pill warn\">Partial release</span><small>'+g.held.map(r=>esc(r.unit)+' × '+(r.qty-ERP.purchased(state,r.id))+' unreleased').join('<br>')+'</small>':'All demand released'}</td><td>${dates[0]||'Not scheduled'}</td><td><button class=\"primary\" data-order=\"${g.part.id}\">Record purchase</button></td></tr>`}))+`<h2>Confirmed purchase history</h2>`+table(['Component / unit','Quantity','Unit price','Tax + shipping','Date'],state.orders.map(o=>{const r=state.requirements.find(r=>r.id===o.requirement);return `<tr><td>${esc(part(r).name)}<small>${esc(r.unit)}</small></td><td>${o.qty}</td><td>${money(o.price)}</td><td>${money(o.extra)}</td><td>${esc(o.date)||'Not recorded'}</td></tr>`})),\r\n'Budget':()=>{const rows=state.units.filter(u=>u.name!=='Documentation');const expected=sum(physical(),exp),actual=sum(physical(),act),allocated=sum(rows,u=>u.budget??0);return title('FINANCIAL OVERVIEW','Budget','Expected includes design-stage requirements. Actual includes confirmed purchases only.')+`<div class=\"metrics\">${metric('Total allocation',money(3000),'Fixed team budget')}${metric('Expected / budget',money(expected)+' / $3,000','Remaining forecast: '+money(3000-expected))}${metric('Actual / budget',money(actual)+' / $3,000','Unspent: '+money(3000-actual))}${metric('Unallocated mechanical',money(3000-allocated),'Divide $2,100 among five mechanical units')}</div><div class=\"banner\">Current costs exclude tax and shipping until entered against purchases. Unknown estimates are flagged rather than treated as complete budgets. Unit allocations must total $3,000.${allocated>3000?' <b>Allocations currently exceed the team budget.</b>':''}</div>`+table(['Unit','Budget allocation','Expected / budget','Actual / budget','Forecast remaining'],rows.map(u=>{let e=sum(reqs(u.name),exp),a=sum(reqs(u.name),act);return `<tr><td><strong>${u.name}</strong></td><td><input class=\"budgetinput\" aria-label=\"${u.name} budget\" type=\"number\" min=\"0\" step=\"0.01\" data-budget=\"${u.name}\" value=\"${u.budget??''}\" placeholder=\"Unallocated\"></td><td>${money(e)} / ${u.budget===null?'Unallocated':money(u.budget)}${reqs(u.name).some(r=>part(r).price===null)?'<small class=\"danger\">Unpriced components</small>':''}</td><td>${money(a)} / ${u.budget===null?'Unallocated':money(u.budget)}</td><td>${u.budget===null?'—':money(u.budget-e)}</td></tr>`}))+`<footer>Components are charged once to their assigned unit. Assembly names group work without adding duplicate costs.</footer>`}\r\n};\r\nfunction safeLink(url,label){try{let u=new URL(url);return ['http:','https:'].includes(u.protocol)?`<a href=\"${esc(u.href)}\" target=\"_blank\" rel=\"noopener noreferrer\">${label}</a>`:''}catch{return ''}}\r\nfunction table(headers,rows){return `<div class=\"tablewrap\"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan=\"${headers.length}\" class=\"empty\">No items yet. Add a component or release a requirement to continue.</td></tr>`}</tbody></table></div>`}\r\nfunction partsPage(inventory){let rs=physical().filter(r=>(!filter||r.unit===filter)&&(!search||(part(r).name+' '+part(r).number+' '+r.assembly).toLowerCase().includes(search.toLowerCase()))&&(!inventory||r.received>0||['Purchased','Fabricating','Ready for assembly','Assembled'].includes(r.stage)));let html=title(inventory?'MATERIAL FLOW':'ENGINEERING REGISTER',inventory?'Inventory & fabrication':'Master parts',inventory?'Record room locations, quantities, and fabrication readiness.':'One component record can supply requirements in multiple units.','<button class=\"primary\" data-add>Add component +</button>')+`<div class=\"filters\"><input id=\"search\" placeholder=\"Search parts, numbers, assemblies\" value=\"${esc(search)}\"><select id=\"filter\" aria-label=\"Filter unit\"><option value=\"\">All units</option>${opts(names.filter(n=>n!=='Documentation'),filter)}</select></div>`+table(['Component / assembly','Unit','Qty / received / ready','Stage','Location','Estimate',''],rs.map(r=>`<tr><td><strong>${esc(part(r).name)}</strong><small>${esc(part(r).number)||'No part number'} ${r.assembly?' · '+esc(r.assembly):''}</small>${safeLink(part(r).drawing,'Drawing '+(part(r).revision||''))}</td><td>${esc(r.unit)}</td><td>${r.qty} / ${r.received} / ${r.ready}</td><td>${badge(r.stage)}</td><td>${esc(r.location)||'Not assigned'}</td><td>${part(r).price===null?'<span class=\"pill warn\">Unpriced</span>':money(exp(r))}</td><td><button data-edit=\"${r.id}\">Edit</button></td></tr>`));if(inventory){let assemblies=[...new Set(rs.map(r=>r.assembly).filter(Boolean))];html+='<h2>Assembly readiness</h2>'+assemblies.map(a=>{let all=physical().filter(r=>r.assembly===a),ready=all.every(r=>r.ready>=r.qty);return `<div class=\"panel\"><h3>${esc(a)}</h3>${badge(ready?'Ready for assembly':'Awaiting components')}<p>${all.map(r=>esc(part(r).name)+': '+r.ready+'/'+r.qty+' ready').join(' · ')}</p><small>For weldments: mark fabricated components ready, then record welding/assembly completion on the component requirements.</small></div>`}).join('')}return html}\r\nfunction modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}\r\nfunction field(label,name,value='',type='text',extra=''){return `<label>${label}<input name=\"${name}\" type=\"${type}\" value=\"${esc(value)}\" ${extra}></label>`}\r\nfunction editor(id,doc=false){let r=state.requirements.find(r=>r.id===id),p=r?part(r):{};doc=doc||r?.unit==='Documentation';modal(`<form id=\"editor\"><h2>${r?'Edit':'Add'} ${doc?'document':'component requirement'}</h2><div class=\"formgrid\">${!r&&!doc?`<label class=\"full\">Use existing component (groups shared purchasing)<select name=\"existing\"><option value=\"\">Create new component</option>${state.parts.filter(p=>p.type!=='Document').map(p=>`<option value=\"${p.id}\">${esc(p.name)} · ${esc(p.number)}</option>`).join('')}</select></label>`:''}${field('Name','name',p.name||'','text',r?'required':'')}${field('Part number','number',p.number||'')}${doc?'<input type=\"hidden\" name=\"unit\" value=\"Documentation\">':`<label>Unit<select name=\"unit\">${opts(names.filter(n=>n!=='Documentation'),r?.unit||'Drivetrain')}</select></label>`}${field(doc?'Deadline':'Parent assembly / weldment','assembly',doc?r?.due||'':r?.assembly||'',doc?'date':'text')}${field('Drawing / document URL','drawing',p.drawing||'','url')}${field('Revision','revision',p.revision||'')}${!doc?`${field('Required quantity','qty',r?.qty??1,'number','min=\"1\" step=\"1\" required')}${field('Estimated unit price (blank = unknown)','price',p.price??'','number','min=\"0\" step=\"0.01\"')}${field('Supplier','supplier',p.supplier||'')}${field('Product URL','url',p.url||'','url')}<label>Component type<select name=\"type\">${opts(['Purchased','Fabricated','Assembly'],p.type||'Purchased')}</select></label><label>Stage<select name=\"stage\">${opts(ERP.stages,r?.stage||'Design')}</select></label>${field('Received quantity','received',r?.received??0,'number','min=\"0\" step=\"1\"')}${field('Fabricated / assembly-ready quantity','ready',r?.ready??0,'number','min=\"0\" step=\"1\"')}${field('Room location (rack / shelf / bin)','location',r?.location||'')}`:`<label>Status<select name=\"stage\">${opts(['Design','In review','Released','Complete'],r?.stage||'Design')}</select></label>`}<label class=\"full\">Notes / owner<textarea name=\"notes\">${esc(r?.notes||'')}</textarea></label></div><p class=\"sub\">Component identity, price, and drawing changes apply everywhere this component is used. Quantities and stage belong to this unit. Purchases are recorded in Purchasing.</p><div class=\"actions\"><button type=\"button\" data-close>Cancel</button><button class=\"primary\">Save</button></div></form>`);$('#editor').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),existing=f.existing?state.parts.find(p=>p.id===f.existing):null;if(!existing&&!f.name.trim())return alert('Enter a component name.');let qty=doc?1:+f.qty,received=doc?0:+f.received,ready=doc?0:+f.ready;if(received>qty||ready>received)return alert('Ready quantity cannot exceed received, and received cannot exceed required.');if(!doc&&['Ready for assembly','Assembled'].includes(f.stage)&&ready<qty)return alert('Mark the full required quantity ready before selecting that stage.');if(!doc&&['Received','Fabricating'].includes(f.stage)&&received===0)return alert('Enter received quantity first.');if(r&&qty<ERP.purchased(state,r.id))return alert('Required quantity cannot be below recorded purchases.');let np=existing||p;if(!existing){if(!np.id)np={id:uid()};Object.assign(np,{name:f.name.trim(),number:f.number,price:doc?null:f.price===''?null:+f.price,supplier:f.supplier||'',url:f.url||'',drawing:f.drawing,revision:f.revision,type:doc?'Document':f.type});if(!p.id)state.parts.push(np)}let nr=r||{id:uid()};Object.assign(nr,{part:np.id,unit:f.unit,qty,received,ready,stage:f.stage,location:f.location||'',assembly:doc?'':f.assembly,due:doc?f.assembly:'',notes:f.notes});if(!r)state.requirements.push(nr);$('#modal').close();save()}}\r\nfunction order(id){const g=ERP.groups(state).find(g=>g.part.id===id);modal(`<form id=\"purchase\"><h2>Record purchase · ${esc(g.part.name)}</h2><p>Enter the quantities actually purchased for each released unit.</p><div class=\"formgrid\">${g.released.map(r=>field(r.unit+' (up to '+(r.qty-ERP.purchased(state,r.id))+')',r.id,r.qty-ERP.purchased(state,r.id),'number',`min=\"0\" max=\"${r.qty-ERP.purchased(state,r.id)}\" step=\"1\" required`)).join('')}${field('Confirmed price per item','price',g.part.price??'','number','min=\"0\" step=\"0.01\" required')}${field('Total tax + shipping for this line','extra',0,'number','min=\"0\" step=\"0.01\" required')}${field('Purchase date','date',new Date().toLocaleDateString('en-CA'),'date','required')}</div><div class=\"actions\"><button type=\"button\" data-close>Cancel</button><button class=\"primary\">Confirm purchased</button></div></form>`);$('#purchase').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),total=sum(g.released,r=>+f[r.id]);if(!total)return alert('Enter at least one purchased item.');g.released.forEach(r=>{let qty=+f[r.id];if(!qty)return;state.orders.push({id:uid(),requirement:r.id,qty,price:+f.price,extra:+f.extra*qty/total,date:f.date,note:''});if(ERP.purchased(state,r.id)>=r.qty&&r.stage==='Released')r.stage='Purchased'});$('#modal').close();save()}}\r\nfunction bind(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>editor());document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>editor(null,true));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(b.dataset.edit));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>order(b.dataset.order));document.querySelectorAll('[data-date]').forEach(i=>i.onchange=()=>{state.units.find(u=>u.name===i.dataset.unit)[i.dataset.date]=i.value;save()});document.querySelectorAll('[data-budget]').forEach(i=>i.onchange=()=>{state.units.find(u=>u.name===i.dataset.budget).budget=i.value===''?null:+i.value;save()});if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render()};if($('#search'))$('#search').oninput=e=>{search=e.target.value;let pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}}\r\n$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='lunabotics-erp-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const n=JSON.parse(await e.target.files[0].text());if(n.version!==1||!Array.isArray(n.units)||names.some(name=>!n.units.some(u=>u.name===name))||!['parts','requirements','orders'].every(k=>Array.isArray(n[k])))throw Error('Invalid backup structure');if(n.parts.some(p=>typeof p.id!=='string'||typeof p.name!=='string'||(p.price!==null&&(!Number.isFinite(p.price)||p.price<0)))||n.requirements.some(r=>!n.parts.some(p=>p.id===r.part)||!names.includes(r.unit)||![r.qty,r.received,r.ready].every(x=>Number.isFinite(x)&&x>=0)||r.received>r.qty||r.ready>r.received)||n.orders.some(o=>!n.requirements.some(r=>r.id===o.requirement)||![o.qty,o.price,o.extra].every(x=>Number.isFinite(x)&&x>=0)))throw Error('Invalid or inconsistent records');if(confirm('Replace the SHARED CLUB WORKSPACE with this backup? Everyone will see these records. Export the current cloud records first if needed.')){state=n;save()}}catch(err){alert('Import failed: '+err.message)}e.target.value=''};startCloud();\r\n","type":"text/javascript; charset=utf-8"},"/logic.js":{"body":"(function(root){\nconst stages=['Design','Released','Purchased','Received','Fabricating','Ready for assembly','Assembled'];\nfunction purchased(s,id){return s.orders.filter(o=>o.requirement===id).reduce((a,o)=>a+o.qty,0)}\nfunction actual(s,id){return s.orders.filter(o=>o.requirement===id).reduce((a,o)=>a+o.qty*o.price+o.extra,0)}\nfunction expected(s,r){const p=s.parts.find(p=>p.id===r.part);return actual(s,r.id)+Math.max(0,r.qty-purchased(s,r.id))*(p.price??0)}\nfunction groups(s){return s.parts.map(p=>{const all=s.requirements.filter(r=>r.part===p.id&&r.unit!=='Documentation');const released=all.filter(r=>r.stage!=='Design'&&r.qty>purchased(s,r.id));const held=all.filter(r=>r.stage==='Design'&&r.qty>purchased(s,r.id));return {part:p,released,held,qty:released.reduce((a,r)=>a+Math.max(0,r.qty-purchased(s,r.id)),0)}}).filter(g=>g.qty>0)}\nconst api={stages,purchased,actual,expected,groups};if(typeof module!=='undefined')module.exports=api;else root.ERP=api;\n})(globalThis);\n","type":"text/javascript; charset=utf-8"},"/style.css":{"body":"@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');\n:root{font-family:'DM Sans',sans-serif;color:#182c38;background:#f3f5f5;font-size:14px}*{box-sizing:border-box}body{margin:0}aside{width:240px;position:fixed;inset:0 auto 0 0;background:#102b38;color:white;padding:32px 20px;display:flex;flex-direction:column}.brand{display:flex;gap:12px;font-family:'Space Grotesk',sans-serif;font-size:22px;color:#99e0c4;font-weight:700}.brand span{font-size:17px;color:#fff}.brand small{display:block;font-size:9px;letter-spacing:1.6px;margin-top:8px;color:#9aafb8}nav{margin-top:45px;display:grid;gap:8px}nav button{text-align:left;background:none;color:#adc0c9;border:0;padding:13px 16px;font-size:14px}nav button.active{background:#244651;color:#c0f3dd;border-left:3px solid #99e0c4;border-radius:4px}.sidefoot{margin-top:auto;font-size:10px;letter-spacing:1px;color:#b4c7cf}.sidefoot span{display:block;margin-top:10px;font-size:11px;letter-spacing:0;color:#78929e}main{margin-left:240px}header{height:76px;padding:20px 36px;background:white;border-bottom:1px solid #dfe5e7;display:flex;align-items:center;justify-content:space-between}header>span{font-size:11px;letter-spacing:1.5px;color:#6b7d85}header b{margin:0 13px;color:#b0c0c6}.notice{padding:11px 36px;background:#e8f0ed;color:#426458;font-size:11px}section{padding:32px 36px}h1,h2,h3,.metric strong{font-family:'Space Grotesk',sans-serif}h1{font-size:32px;margin:6px 0 8px;letter-spacing:-1px}h2{font-size:19px}h3{margin:0 0 12px;font-size:17px}p{color:#657b84;line-height:1.6}.eyebrow{color:#688078;letter-spacing:1.8px;font-size:10px;font-weight:700}.title{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:25px 0}.metric,.panel,.unit{background:white;border:1px solid #dde5e6;border-radius:10px;padding:22px}.metric label{display:block;font-size:12px;color:#647b84}.metric strong{display:block;font-size:28px;margin:12px 0}.metric small{color:#71848c}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.unit .unithead{display:flex;justify-content:space-between}.pill{display:inline-block;padding:5px 8px;border-radius:5px;background:#edf1f3;font-size:11px;white-space:nowrap}.pill.green{background:#e0f3e9;color:#236846}.pill.warn{background:#fff0d3;color:#8b6011}.dates{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:18px;font-size:11px;color:#637780}.dates input{width:100%;margin-top:7px}.progress{height:5px;background:#eaf0ee;margin-top:16px;border-radius:5px;overflow:hidden}.progress i{height:100%;display:block;background:#4c9e7a}.tablewrap{overflow:auto;background:white;border:1px solid #dce4e6;border-radius:9px}table{border-collapse:collapse;width:100%;font-size:12px}th{background:#edf2f2;color:#677d86;font-size:10px;text-transform:uppercase;letter-spacing:.6px;text-align:left;padding:14px}td{padding:14px;border-top:1px solid #e8eded;vertical-align:middle}td strong{display:block;font-size:13px}td small{display:block;color:#788a91;margin-top:4px}.filters{display:flex;gap:10px;margin-bottom:18px;flex-wrap:wrap}button,input,select,textarea{font:inherit;border:1px solid #cedadd;border-radius:6px;padding:9px 11px;background:white;color:#243e4a}button{cursor:pointer}button:hover{border-color:#528f78;background:#edf5f1}button.primary{background:#163f43;color:white;border-color:#163f43}button.link{padding:0;background:none;border:0;color:#227356}input[type=number]{width:100px}input:focus,select:focus,textarea:focus{outline:2px solid #90c8b4;outline-offset:1px}.empty{padding:30px;color:#6c8088;text-align:center}.muted{color:#6e828a}.banner{background:#fff4db;border:1px solid #ebd8a7;padding:14px 18px;border-radius:7px;margin:16px 0;color:#785c21;font-size:12px}dialog{border:0;border-radius:12px;padding:28px;width:min(620px,95vw);max-height:90vh;overflow:auto;box-shadow:0 20px 80px #102b3855}dialog::backdrop{background:#102b3880}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.formgrid label{display:grid;gap:7px;font-size:12px}.formgrid input,.formgrid select,.formgrid textarea{width:100%}.full{grid-column:1/-1}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}.money{font-variant-numeric:tabular-nums;white-space:nowrap}.split{display:grid;grid-template-columns:2fr 1fr;gap:20px}.row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #e8eeee}a{color:#22755d}footer{margin-top:18px;color:#7a8c94;font-size:11px}.sub{font-size:12px;color:#6c8088}.budgetinput{width:110px!important}.danger{color:#a33925}.check{margin:12px 0;display:block} @media(max-width:1050px){aside{width:190px}main{margin-left:190px}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.split{grid-template-columns:1fr}section{padding:24px}.dates{grid-template-columns:1fr}}@media(max-width:650px){aside{position:static;width:auto;padding:18px}.sidefoot{display:none}nav{margin-top:16px;display:flex;overflow:auto;gap:3px}nav button{white-space:nowrap;padding:9px}main{margin:0}header{padding:12px 18px;height:auto;gap:10px;flex-wrap:wrap}.notice{padding:10px 18px}section{padding:20px 15px}h1{font-size:27px}.metrics{gap:10px}.metric{padding:15px}.metric strong{font-size:23px}.title{gap:10px}.formgrid{grid-template-columns:1fr}.full{grid-column:auto}}\n.dates label,.dates input,.unit,.split>div{min-width:0}.dates input{padding:8px 5px;font-size:11px}.unithead{gap:8px}.unithead h3{overflow-wrap:anywhere}\r\n","type":"text/css; charset=utf-8"},"/cloud.js":{"body":"let cloudEtag=null,cloudBusy=false,cloudFailed=false,cloudReady=false,cloudUser='',cloudMeta={};\r\nconst notice=html=>document.querySelector('.notice').innerHTML=html;\r\nfunction cloudControls(disabled){document.querySelectorAll('#app button,#app input,#app select,#import').forEach(e=>e.disabled=disabled)}\r\nfunction cloudStatus(){notice(`SHARED CLOUD WORKSPACE · Signed in as ${esc(cloudUser)} · ${cloudMeta.updatedAt?'Saved '+esc(new Date(cloudMeta.updatedAt).toLocaleString())+' by '+esc(cloudMeta.updatedBy):'Ready'} · Updates refresh automatically. <a href=\"/signout-with-chatgpt?return_to=%2F\" target=\"_top\">Sign out</a>`)}\r\nasync function cloudRequest(path,options){const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});let data;try{data=await response.json()}catch{throw Error('The server did not return workspace data. Sign in again or retry.')}if(!response.ok){const e=Error(data.error||'Cloud request failed.');e.status=response.status;throw e}return data}\r\nfunction downloadDraft(){document.querySelector('#export').click()}\r\nfunction cloudError(error){cloudFailed=true;cloudControls(true);notice(`<strong>Not saved to cloud.</strong> ${esc(error.message)} <button id=\"export-draft\">Export unsaved draft</button> <button id=\"reload-cloud\">Reload cloud records</button>${error.status===409?'':' <button id=\"retry-cloud\">Retry save</button>'}`);document.querySelector('#export-draft').onclick=downloadDraft;document.querySelector('#reload-cloud').onclick=()=>{if(confirm('Discard the unsaved draft and load the shared cloud records? Export the draft first if needed.'))location.reload()};if(document.querySelector('#retry-cloud'))document.querySelector('#retry-cloud').onclick=()=>{cloudFailed=false;cloudSave()}}\r\nasync function cloudSave(){if(cloudBusy||cloudFailed)return;cloudBusy=true;cloudControls(true);notice('Saving to the shared club workspace…');try{const data=await cloudRequest('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state,etag:cloudEtag})});cloudEtag=data.etag;cloudMeta=data;cloudReady=true;render();cloudStatus()}catch(error){cloudError(error)}finally{cloudBusy=false;if(!cloudFailed)cloudControls(false)}}\r\nfunction startWorkspace(value){state=structuredClone(value);render();cloudSave()}\r\nasync function startCloud(){cloudControls(true);document.querySelector('#app').innerHTML='<div class=\"panel\"><h2>Loading shared workspace</h2><p>Connecting securely to the club’s cloud records…</p></div>';try{const session=await cloudRequest('/api/session');cloudUser=session.email||'Club member';const data=await cloudRequest('/api/state');cloudEtag=data.etag;cloudMeta=data;if(data.state){state=data.state;cloudReady=true;render();cloudControls(false);cloudStatus()}else{\r\n let local;try{local=JSON.parse(localStorage.getItem('luna-erp-v1'))}catch{};\r\n document.querySelector('#app').innerHTML=`<div class=\"panel\"><div class=\"eyebrow\">FIRST-TIME SETUP</div><h1>Create the shared club workspace</h1><p>No cloud records have been created yet. Choose the starting data. This creates one shared workspace for every authorized member.</p><button class=\"primary\" id=\"start-budget\">Start with the master-budget parts</button> ${local?'<button id=\"migrate-local\">Import this browser’s existing records</button>':''}<p>To use a backup file, first start the workspace, then choose Import backup. Existing browser data is left untouched.</p></div>`;\r\n document.querySelector('#start-budget').onclick=()=>startWorkspace(seed);if(local)document.querySelector('#migrate-local').onclick=()=>{if(confirm('Upload this browser’s existing ERP records as the shared club workspace?'))startWorkspace(local)};notice('Signed in as '+esc(cloudUser)+' · Cloud storage is connected. Choose initial records.');\r\n }\r\n }catch(error){document.querySelector('#app').innerHTML=`<div class=\"panel\"><h2>Workspace could not load</h2><p>${esc(error.message)}</p><button onclick=\"location.reload()\">Retry connection</button> <a href=\"/signin-with-chatgpt?return_to=%2F\" target=\"_top\">Sign in</a></div>`;notice('Cloud records have not been loaded. No records were changed.')} }\r\nasync function refreshCloud(){if(!cloudReady||cloudBusy||cloudFailed||document.visibilityState==='hidden'||document.querySelector('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{const data=await cloudRequest('/api/state');if(data.state&&data.etag!==cloudEtag){state=data.state;cloudEtag=data.etag;cloudMeta=data;render()}cloudStatus()}catch{notice('Connection interrupted. Displaying the last loaded cloud records. Changes will only be marked saved after the server confirms.')}}\r\nsetInterval(refreshCloud,10000);window.addEventListener('focus',refreshCloud);window.addEventListener('beforeunload',e=>{if(cloudBusy||cloudFailed){e.preventDefault();e.returnValue='Unsaved changes'}});\r\n","type":"text/javascript; charset=utf-8"}};
const units=['Drivetrain','Chassis','Shoulder','Legs','Drum','Electronics','Misc','Documentation'];
const key='club/erp/state-v1.json';
const json=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
export function validate(s){
 if(!s||s.version!==1||!['units','parts','requirements','orders'].every(k=>Array.isArray(s[k])&&s[k].length<=5000))return 'Invalid record structure.';
 const unique=a=>a.every(x=>x&&typeof x.id==='string'&&x.id.length<=100)&&new Set(a.map(x=>x.id)).size===a.length;
 const num=x=>Number.isFinite(x)&&x>=0;const text=(x,max=2000)=>typeof x==='string'&&x.length<=max;const date=x=>x===''||typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x);
 if(s.units.length!==8||new Set(s.units.map(u=>u.name)).size!==8||s.units.some(u=>!units.includes(u.name)||!(u.budget===null||num(u.budget))||!['purchase','fabricate','assemble'].every(k=>date(u[k]))))return 'Invalid units, budgets, or deadlines.';
 if(!unique(s.parts)||!unique(s.requirements)||!unique(s.orders))return 'Missing or duplicate record IDs.';
 const parts=new Map(s.parts.map(p=>[p.id,p]));const reqs=new Map(s.requirements.map(r=>[r.id,r]));
 if(s.parts.some(p=>!text(p.name,200)||!p.name.trim()||!(p.price===null||num(p.price))||!['number','supplier','url','drawing','revision','type'].every(k=>text(p[k]))||!['url','drawing'].every(k=>!p[k]||/^https?:\/\//i.test(p[k]))))return 'Invalid component details, price, or links.';
 if(s.requirements.some(r=>!parts.has(r.part)||!units.includes(r.unit)||!Number.isInteger(r.qty)||r.qty<1||!['qty','received','ready'].every(k=>Number.isInteger(r[k])&&r[k]>=0)||r.received>r.qty||r.ready>r.received||!['location','assembly','notes'].every(k=>text(r[k],6000))||!date(r.due)||!(r.unit==='Documentation'?['Design','In review','Released','Complete']:['Design','Released','Purchased','Received','Fabricating','Ready for assembly','Assembled']).includes(r.stage)||['Ready for assembly','Assembled'].includes(r.stage)&&r.ready<r.qty))return 'Invalid requirement, quantities, or stage.';
 if(s.orders.some(o=>!reqs.has(o.requirement)||!Number.isInteger(o.qty)||o.qty<1||!num(o.price)||!num(o.extra)||!date(o.date)||!text(o.note,6000)))return 'Invalid purchase.';
 const ordered=new Map();for(const o of s.orders)ordered.set(o.requirement,(ordered.get(o.requirement)||0)+o.qty);if([...ordered].some(([id,qty])=>qty>reqs.get(id).qty))return 'Purchased quantity exceeds required quantity.';
 return null;
}
export default {async fetch(request,env){try{
 const url=new URL(request.url);const user=request.headers.get('oai-authenticated-user-id');
 // The Sites gateway enforces the site's member allowlist and supplies verified identity.
 if(!user){if(url.pathname.startsWith('/api/'))return json({error:'Sign in to access the club workspace.'},401);return Response.redirect(url.origin+'/signin-with-chatgpt?return_to=%2F',302)}
 if(url.pathname==='/api/session')return json({email:request.headers.get('oai-authenticated-user-email')||'',id:user});
 if(url.pathname==='/api/state'){
  if(!env.BUCKET)return json({error:'Cloud storage is unavailable. No changes were saved.'},503);
  if(request.method==='GET'){
   const obj=await env.BUCKET.get(key);return obj?json({...(await obj.json()),etag:obj.etag}):json({state:null,etag:null});
  }
  if(request.method!=='PUT')return json({error:'Method not allowed.'},405);
  if(request.headers.get('Origin')!==url.origin)return json({error:'Cross-site writes are not allowed.'},403);
  if(!(request.headers.get('Content-Type')||'').startsWith('application/json'))return json({error:'JSON required.'},415);
  if(+(request.headers.get('Content-Length')||0)>1500000)return json({error:'Workspace is too large.'},413);
  const raw=await request.text();if(raw.length>1500000)return json({error:'Workspace is too large.'},413);
  let input;try{input=JSON.parse(raw)}catch{return json({error:'Invalid JSON.'},400)}
  const invalid=validate(input.state);if(invalid)return json({error:invalid},400);
  if(input.etag!==null&&(typeof input.etag!=='string'||!/^[a-f0-9]{32}$/.test(input.etag)))return json({error:'Invalid workspace revision.'},400);
  const current=await env.BUCKET.get(key);
  if((current?.etag??null)!==input.etag)return json({error:'Another member saved changes. Export your draft, then reload the latest workspace.'},409);
  const data={state:input.state,updatedAt:new Date().toISOString(),updatedBy:request.headers.get('oai-authenticated-user-email')||user};
  const result=await env.BUCKET.put(key,JSON.stringify(data),{onlyIf:input.etag?{etagMatches:input.etag}:{etagDoesNotMatch:'*'},httpMetadata:{contentType:'application/json'}});
  if(!result)return json({error:'Another member saved at the same time. Export your draft and reload.'},409);
  return json({...data,etag:result.etag});
 }
 const asset=assets[url.pathname];if(!asset)return new Response('Not found',{status:404});
 return new Response(asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin'}});
 }catch{return json({error:'Cloud request failed. Your draft has not been discarded.'},503)}}};
